import math


def estimate_tokens(text):
    return math.ceil(len(text) / 4)


def fit_transcript(instructions, turns, limit, reply_budget):
    used = estimate_tokens(instructions) + reply_budget
    if used > limit:
        raise ValueError("instructions and reply do not fit")
    kept = []
    for turn in reversed(turns):
        cost = estimate_tokens(turn)
        if used + cost > limit:
            break
        kept.append(turn)
        used += cost
    return kept[::-1]

