lessons.solution:
from dataclasses import fields


def schema(cls):
    result = {}
    for f in fields(cls):
        entry = {
            "type": f.type.__name__,
            "description": f.metadata.get("description", ""),
        }
        for key in ("choices", "range"):
            if key in f.metadata:
                entry[key] = f.metadata[key]
        result[f.name] = entry
    return result


def valid(f, data):
    if f.name not in data:
        return False
    value = data[f.name]
    if type(value) is not f.type:
        return False
    choices = f.metadata.get("choices")
    if choices is not None and value not in choices:
        return False
    bounds = f.metadata.get("range")
    if bounds is not None:
        low, high = bounds
        if not low <= value <= high:
            return False
    return True


def validate(cls, data):
    bad = [f.name for f in fields(cls) if not valid(f, data)]
    if bad:
        raise ValueError("invalid: " + ", ".join(bad))
    return cls(**{f.name: data[f.name] for f in fields(cls)})

