import re

SENTENCE_END = re.compile(r"[.!?](?=\s|$)")


def deltas(snapshots):
    parts = []
    previous = ""
    for snapshot in snapshots:
        if not snapshot.startswith(previous):
            raise ValueError("snapshot does not extend the last one")
        if len(snapshot) > len(previous):
            parts.append(snapshot[len(previous):])
        previous = snapshot
    return parts


def complete_sentences(text):
    ends = list(SENTENCE_END.finditer(text))
    if not ends:
        return ""
    return text[:ends[-1].end()]

