class GuardrailViolation(Exception):
    pass


class ContextTooLong(Exception):
    pass


def failure(error, calls):
    return {"ok": False, "error": error, "calls": calls}


def ask(model, prompt, validate, attempts=3):
    current = prompt
    for calls in range(1, attempts + 1):
        try:
            reply = model(current)
        except GuardrailViolation:
            return failure("guardrail", calls)
        except ContextTooLong:
            return failure("too long", calls)
        try:
            value = validate(reply)
        except ValueError as error:
            current = (prompt + "\n\nYour last reply was invalid: "
                       + str(error))
            continue
        return {"ok": True, "value": value, "calls": calls}
    return failure("invalid", attempts)

