def exact(output, expected):
    return output.strip().lower() == expected.strip().lower()


def contains_all(output, words):
    text = output.lower()
    return all(word.lower() in text for word in words)


def passes(model, case, scorer):
    text, expected = case
    try:
        return bool(scorer(model(text), expected))
    except Exception:
        return False


def evaluate(model, cases, scorer):
    failures = [case[0] for case in cases
                if not passes(model, case, scorer)]
    total = len(cases)
    passed = total - len(failures)
    return {
        "passed": passed,
        "total": total,
        "rate": passed / total if total else 0.0,
        "failures": failures,
    }


def compare(model_a, model_b, cases, scorer):
    a = evaluate(model_a, cases, scorer)["passed"]
    b = evaluate(model_b, cases, scorer)["passed"]
    if a == b:
        return "tie"
    return "a" if a > b else "b"

